const visual = {
  prepare: function (input) { return []; },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var margin = Math.min(w, h) * 0.1;
    var side = Math.min(w, h) - 2 * margin;
    var x0 = (w - side) / 2;
    var y0 = (h - side) / 2;
    var step = side / 4;
    var paths = [];
    var children = [];
    var i, k;
    for (i = 0; i <= 4; i++) {
      var x = x0 + i * step;
      paths.push({ id: 'v' + i, commands: [['M', x, y0], ['L', x, y0 + side]] });
    }
    for (i = 0; i <= 4; i++) {
      var y = y0 + i * step;
      paths.push({ id: 'h' + i, commands: [['M', x0, y], ['L', x0 + side, y]] });
    }
    for (k = 0; k < paths.length; k++) {
      children.push({ type: 'path', pathId: paths[k].id, fill: '#26354a', stroke: { width: 2 } });
    }
    return {
      schemaVersion: 1,
      sceneId: 'grid-4x4',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
